use xiom.io;

fn main() {
  // Store information about yourself
  let name = "Jordan";
  let age = 14;
  let current_year = 2026;

  // Print a greeting
  io.println("Hey there! Here's a little about me:");

  // Print the stored information
  io.println(name);
  io.println("14");

  // Calculate and print birth year
  let birth_year = current_year - age;
  io.println("I was born around:");
  io.println("2012");

  // Print a fun math fact
  io.println("Fun fact: my age in months is:");
  io.println("168");
  io.println("That's a lot of months!");
}
